g.data-latex:
// 向量召回工具
  recall_items(user_id, query_text, top_{k}) \to item_list
  // 精排工具
  rank_items(user_id, item_list) \to ranked_list
  // 知识查询工具
  query_knowledge(item_id) \to item_attributes
  // 搭配推荐工具
  get_matching_items(item_id, matching_type) \to matched_items
  // 多模态理解工具
  understand_image(image_url) \to text_description
